import urllib.request
import os
import csv
import collections

def task_func(url, column_name, csv_file_path):
    downloaded = False
    try:
        urllib.request.urlretrieve(url, csv_file_path)
        downloaded = True

        with open(csv_file_path, mode="r", newline="", encoding="utf-8") as f:
            reader = csv.DictReader(f)

            if reader.fieldnames is None or column_name not in reader.fieldnames:
                raise ValueError(
                    f"The provided column_name '{column_name}' does not exist in the CSV file."
                )

            counts = collections.Counter()
            for row in reader:
                counts[row[column_name]] += 1

        return dict(counts)

    finally:
        if downloaded and os.path.exists(csv_file_path):
            try:
                os.remove(csv_file_path)
            except OSError:
                pass
